alert("testui");$('#openChat').click(function(){$('#chatPopup').show();});$(document).click(function(e){if(!$(e.target).closest('#chatPopup, #openChat').length){$('#chatPopup').hide();}});$('#sendMessage').click(function(){let userInput=$('#userInput').val();if(userInput!==''){$('#messages').append('<div>You: '+userInput+'</div>');setTimeout(function(){$('#messages').append('<div>Bot: Hi! I am a chatbot.</div>');$('.chat-content').scrollTop($('.chat-content')[0].scrollHeight);},500);$('#userInput').val('');}});